use std::collections::HashMap;
use std::sync::{Mutex, OnceLock, atomic::{AtomicUsize, Ordering}, mpsc::{self, Sender, Receiver}};
use std::thread::{self, JoinHandle};

pub mod ast;
pub mod cli;
pub mod lexer;
pub mod parser;
pub mod runtime;
pub mod typecheck;
use std::collections::HashMap as Map;

static THREADS: OnceLock<Mutex<Map<usize, JoinHandle<Value>>>> = OnceLock::new();
static NEXT_THREAD_ID: AtomicUsize = AtomicUsize::new(1);
static NEXT_CHANNEL_ID: AtomicUsize = AtomicUsize::new(1);
static CHANNELS: OnceLock<Mutex<Map<usize, (Sender<Value>, Receiver<Value>)>>> = OnceLock::new();
fn channel_table() -> &'static Mutex<Map<usize, (Sender<Value>, Receiver<Value>)>> { CHANNELS.get_or_init(|| Mutex::new(Map::new())) }
fn thread_table() -> &'static Mutex<Map<usize, JoinHandle<Value>>> { THREADS.get_or_init(|| Mutex::new(Map::new())) }


pub use ast::{Expr, Function, Stmt, Type, Value};
pub use lexer::{lex, Token};


struct Vm { funcs:HashMap<String,Function> }
impl Vm { fn run(&self)->Result<Value,String>{self.call("main",vec![])} fn call(&self,n:&str,args:Vec<Value>)->Result<Value,String>{if n=="print"{for x in args{println!("{}",show(&x))}return Ok(Value::Unit)}let f=self.funcs.get(n).ok_or_else(||format!("unknown function `{n}`"))?;let mut e=HashMap::new();for(i,p)in f.params.iter().enumerate(){e.insert(p.clone(),args.get(i).cloned().unwrap_or(Value::Unit));}match exec(&f.body,&mut e,self)?{Some(v)=>Ok(v),None=>Ok(Value::Unit)}}}
fn show(v:&Value)->String{match v{Value::Int(x)=>x.to_string(),Value::Str(x)=>x.clone(),Value::Bool(x)=>x.to_string(),Value::Unit=>"unit".into(),Value::Thread(id)=>format!("thread({id})"),Value::Channel(id)=>format!("channel({id})")}}
fn truth(v:&Value)->bool{matches!(v,Value::Bool(true))||matches!(v,Value::Int(x)if *x!=0)}
fn val(x:&Expr,e:&mut HashMap<String,Value>,vm:&Vm)->Result<Value,String>{match x{Expr::Int(x)=>Ok(Value::Int(*x)),Expr::Str(x)=>Ok(Value::Str(x.clone())),Expr::Bool(x)=>Ok(Value::Bool(*x)),Expr::Var(n)=>e.get(n).cloned().ok_or_else(||format!("undefined variable `{n}`")),Expr::Call(n,a)=>{let z=a.iter().map(|x|val(x,e,vm)).collect::<Result<Vec<_>,_>>()?;vm.call(n,z)},Expr::Binary(a,o,b)=>{let x=val(a,e,vm)?;let y=val(b,e,vm)?;bin(x,o,y)}}}
fn bin(a:Value,o:&Token,b:Value)->Result<Value,String>{match (a,b,o){(Value::Int(x),Value::Int(y),Token::Plus)=>Ok(Value::Int(x+y)),(Value::Int(x),Value::Int(y),Token::Minus)=>Ok(Value::Int(x-y)),(Value::Int(x),Value::Int(y),Token::Star)=>Ok(Value::Int(x*y)),(Value::Int(x),Value::Int(y),Token::Slash)=>Ok(Value::Int(x/y)),(Value::Int(x),Value::Int(y),Token::EqEq)=>Ok(Value::Bool(x==y)),(Value::Int(x),Value::Int(y),Token::BangEq)=>Ok(Value::Bool(x!=y)),(Value::Int(x),Value::Int(y),Token::Lt)=>Ok(Value::Bool(x<y)),(Value::Int(x),Value::Int(y),Token::Lte)=>Ok(Value::Bool(x<=y)),(Value::Int(x),Value::Int(y),Token::Gt)=>Ok(Value::Bool(x>y)),(Value::Int(x),Value::Int(y),Token::Gte)=>Ok(Value::Bool(x>=y)),(Value::Str(x),Value::Str(y),Token::Plus)=>Ok(Value::Str(x+&y)),(x,y,Token::EqEq)=>Ok(Value::Bool(x==y)),(x,y,Token::BangEq)=>Ok(Value::Bool(x!=y)),_=>Err("invalid operands".into())}}
fn exec_scoped(xs:&[Stmt],e:&mut HashMap<String,Value>,vm:&Vm)->Result<Option<Value>,String>{let keys:Vec<String>=e.keys().cloned().collect();let shadowed:Vec<String>=xs.iter().filter_map(|s|if let Stmt::Let(n,_)=s{Some(n.clone())}else{None}).collect();let mut inner=e.clone();let result=exec(xs,&mut inner,vm);for k in keys{if !shadowed.contains(&k){if let Some(v)=inner.get(&k){e.insert(k,v.clone());}}}result}
fn exec(xs:&[Stmt],e:&mut HashMap<String,Value>,vm:&Vm)->Result<Option<Value>,String>{for s in xs{match s{Stmt::Let(n,x)|Stmt::Assign(n,x)=>{let value=val(x,e,vm)?;e.insert(n.clone(),value);},Stmt::Decl(n,_)=>{e.insert(n.clone(),Value::Unit);},Stmt::Expr(x)=>{val(x,e,vm)?;},Stmt::Return(x)=>return Ok(Some(val(x,e,vm)?)),Stmt::If(c,a,b)=>{if truth(&val(c,e,vm)?){if let Some(v)=exec_scoped(a,e,vm)?{return Ok(Some(v))}}else if let Some(v)=exec_scoped(b,e,vm)?{return Ok(Some(v))}},Stmt::While(c,b)=>{while truth(&val(c,e,vm)?){if let Some(v)=exec_scoped(b,e,vm)?{return Ok(Some(v))}}}}}Ok(None)}
#[derive(Debug,Clone)] enum Op { Const(Value), Load(String), Store(String), Add, Sub, Mul, Div, Eq, Ne, Lt, Lte, Gt, Gte, Call(String,usize), Print, Pop, JumpIfFalse(usize), Jump(usize), Return, Halt }
#[derive(Debug,Clone)] struct Chunk { code:Vec<Op> }
fn compile_expr(x:&Expr,c:&mut Chunk)->Result<(),String>{match x{Expr::Int(v)=>c.code.push(Op::Const(Value::Int(*v))),Expr::Str(v)=>c.code.push(Op::Const(Value::Str(v.clone()))),Expr::Bool(v)=>c.code.push(Op::Const(Value::Bool(*v))),Expr::Var(n)=>c.code.push(Op::Load(n.clone())),Expr::Binary(a,o,b)=>{compile_expr(a,c)?;compile_expr(b,c)?;c.code.push(match o{Token::Plus=>Op::Add,Token::Minus=>Op::Sub,Token::Star=>Op::Mul,Token::Slash=>Op::Div,Token::EqEq=>Op::Eq,Token::BangEq=>Op::Ne,Token::Lt=>Op::Lt,Token::Lte=>Op::Lte,Token::Gt=>Op::Gt,Token::Gte=>Op::Gte,_=>return Err("invalid bytecode operator".into())})},Expr::Call(n,a)=>{for x in a{compile_expr(x,c)?}c.code.push(if n=="print"{Op::Print}else{Op::Call(n.clone(),a.len())})}}Ok(())}
fn compile_stmts(xs:&[Stmt],c:&mut Chunk)->Result<(),String>{for s in xs{match s{Stmt::Let(n,x)|Stmt::Assign(n,x)=>{compile_expr(x,c)?;c.code.push(Op::Store(n.clone()));},Stmt::Decl(_,_)=>{},Stmt::Expr(x)=>{compile_expr(x,c)?;c.code.push(Op::Pop);},Stmt::Return(x)=>{compile_expr(x,c)?;c.code.push(Op::Return);},Stmt::If(cond,a,b)=>{compile_expr(cond,c)?;let jf=c.code.len();c.code.push(Op::JumpIfFalse(0));compile_stmts(a,c)?;let j=c.code.len();c.code.push(Op::Jump(0));let else_ip=c.code.len();compile_stmts(b,c)?;let end=c.code.len();c.code[jf]=Op::JumpIfFalse(else_ip);c.code[j]=Op::Jump(end);},Stmt::While(cond,b)=>{let start=c.code.len();compile_expr(cond,c)?;let jf=c.code.len();c.code.push(Op::JumpIfFalse(0));compile_stmts(b,c)?;c.code.push(Op::Jump(start));let end=c.code.len();c.code[jf]=Op::JumpIfFalse(end);}}}Ok(())}
fn compile_functions(fs:&[Function])->Result<HashMap<String,(Vec<String>,Chunk)>,String>{let mut out=HashMap::new();for f in fs{let mut c=Chunk{code:Vec::new()};compile_stmts(&f.body,&mut c)?;c.code.push(Op::Const(Value::Unit));c.code.push(Op::Return);out.insert(f.name.clone(),(f.params.clone(),c));}Ok(out)}
pub struct BytecodeVm{funcs:HashMap<String,(Vec<String>,Chunk)>}
impl BytecodeVm{fn call(&self,n:&str,args:Vec<Value>)->Result<Value,String>{if n=="print"{for v in args{println!("{}",show(&v))}return Ok(Value::Unit)}if n=="channel"{let(id_tx,id_rx)=mpsc::channel();let id=NEXT_CHANNEL_ID.fetch_add(1,Ordering::Relaxed);channel_table().lock().unwrap().insert(id,(id_tx,id_rx));return Ok(Value::Channel(id))}if n=="send"{let id=match args.first(){Some(Value::Channel(i))=>*i,_=>return Err("send expects channel".into())};let value=args.get(1).cloned().ok_or("send expects value")?;let table=channel_table().lock().unwrap();let tx=table.get(&id).ok_or("unknown channel")?.0.clone();tx.send(value).map_err(|_|"channel disconnected".to_string())?;return Ok(Value::Unit)}if n=="receive"{let id=match args.first(){Some(Value::Channel(i))=>*i,_=>return Err("receive expects channel".into())};let table=channel_table().lock().unwrap();let rx=table.get(&id).ok_or("unknown channel")?.1.recv().map_err(|_|"channel disconnected".to_string())?;return Ok(rx)}if n=="spawn"{let target=match args.first(){Some(Value::Str(s))=>s.clone(),_=>return Err("spawn expects a function name string".into())};let worker_args=args.into_iter().skip(1).collect::<Vec<_>>();let funcs=self.funcs.clone();let id=NEXT_THREAD_ID.fetch_add(1,Ordering::Relaxed);let handle=thread::spawn(move||BytecodeVm{funcs}.call(&target,worker_args).unwrap_or(Value::Unit));thread_table().lock().unwrap().insert(id,handle);return Ok(Value::Thread(id))}if n=="join"{let id=match args.first(){Some(Value::Thread(i))=>*i,_=>return Err("join expects a thread handle".into())};let handle=thread_table().lock().unwrap().remove(&id).ok_or("unknown thread handle")?;return handle.join().map_err(|_|"thread panicked".into())}let(fparams,chunk)=self.funcs.get(n).ok_or_else(||format!("unknown function `{n}`"))?.clone();let mut locals=HashMap::new();for(i,p)in fparams.iter().enumerate(){locals.insert(p.clone(),args.get(i).cloned().unwrap_or(Value::Unit));}let mut stack=Vec::new();let mut ip=0;while ip<chunk.code.len(){match &chunk.code[ip]{Op::Const(v)=>stack.push(v.clone()),Op::Load(n)=>stack.push(locals.get(n).cloned().ok_or_else(||format!("undefined variable `{n}`"))?),Op::Store(n)=>{let v=stack.pop().ok_or("stack underflow")?;locals.insert(n.clone(),v);},Op::Add|Op::Sub|Op::Mul|Op::Div|Op::Eq|Op::Ne|Op::Lt|Op::Lte|Op::Gt|Op::Gte=>{let b=stack.pop().ok_or("stack underflow")?;let a=stack.pop().ok_or("stack underflow")?;let op=match &chunk.code[ip]{Op::Add=>Token::Plus,Op::Sub=>Token::Minus,Op::Mul=>Token::Star,Op::Div=>Token::Slash,Op::Eq=>Token::EqEq,Op::Ne=>Token::BangEq,Op::Lt=>Token::Lt,Op::Lte=>Token::Lte,Op::Gt=>Token::Gt,Op::Gte=>Token::Gte,_=>unreachable!()};stack.push(bin(a,&op,b)?);},Op::Call(n,c)=>{let mut a=Vec::new();for _ in 0..*c{a.push(stack.pop().ok_or("stack underflow")?)}a.reverse();stack.push(self.call(n,a)?);},Op::Print=>{let v=stack.pop().ok_or("stack underflow")?;println!("{}",show(&v));stack.push(Value::Unit);},Op::Pop=>{stack.pop();},Op::JumpIfFalse(to)=>{let v=stack.pop().ok_or("stack underflow")?;if !truth(&v){ip=*to;continue}},Op::Jump(to)=>{ip=*to;continue},Op::Return=>return Ok(stack.pop().unwrap_or(Value::Unit)),Op::Halt=>return Ok(Value::Unit)}ip+=1}Ok(Value::Unit)}}
pub fn execute(src:&str)->Result<Value,String>{let fs=parser::parse(src)?;typecheck::check(&fs)?;let funcs=compile_functions(&fs)?;BytecodeVm{funcs}.call("main",vec![])}

#[cfg(test)] mod tests {use super::*;#[test]fn worker_can_receive_channel_argument(){let s="fn worker(ch:Channel){send(ch,99);} fn main(){let ch=channel();let t=spawn(\"worker\",ch);join(t);print(receive(ch));}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn channel_send_receive_round_trip(){let s="fn main(){let ch=channel(); send(ch,42); print(receive(ch));}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn recursive_stack_frames_are_isolated(){let s="fn fact(n:Int)->Int{if n==0{return 1;} return n*fact(n-1);} fn main()->Int{return fact(5);}";assert_eq!(execute(s),Ok(Value::Int(120)));}#[test]fn branch_move_is_conservatively_merged(){let s="fn consume(x:String){} fn main(){let s=\"x\"; if true {consume(s);} else {} print(s);}";assert!(execute(s).unwrap_err().contains("use of moved value"));}#[test]fn arithmetic(){let s="fn main(){ print(2+3*4); return 0; }";assert_eq!(execute(s),Ok(Value::Int(0)));}#[test]fn function_call(){let s="fn add(a:Int,b:Int){return a+b;} fn main(){return add(2,3);}";assert_eq!(execute(s),Ok(Value::Int(5)));}#[test]fn unknown_function_is_diagnostic(){let s="fn main(){missing();}";assert!(execute(s).unwrap_err().contains("unknown function"));}#[test]fn type_mismatch_is_diagnostic(){let s="fn add(a:Int,b:Int)->Int{return a+b;} fn main()->Int{return add(2,\"x\");}";assert!(execute(s).unwrap_err().contains("expects Int"));}#[test]fn condition_must_be_bool(){let s="fn main(){if 1 { print(1); }}";assert!(execute(s).unwrap_err().contains("condition must be Bool"));}#[test]fn string_move_is_tracked(){let s="fn consume(x:String){print(x);} fn main(){let a=\"hello\"; consume(a); print(a);}";assert!(execute(s).unwrap_err().contains("use of moved value"));}#[test]fn immutable_borrow_preserves_owner(){let s="fn view(x:&String){print(x);} fn main(){let a=\"hello\"; view(a); print(a);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn mutable_reference_syntax_is_valid(){let s="fn update(x:&mut String){print(x);} fn main(){let a=\"hello\"; update(a); print(a);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn spawn_and_join_run_worker(){let s="fn worker(){print(\"worker\");} fn main(){let t=spawn(\"worker\"); join(t);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn multiple_workers_can_join(){let s="fn worker(){return 7;} fn main(){let a=spawn(\"worker\"); let b=spawn(\"worker\"); join(a); join(b);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn function_locals_do_not_leak(){let s="fn helper(){let secret=1;} fn main(){print(secret);}";assert!(execute(s).unwrap_err().contains("undefined variable"));}#[test]fn assignment_requires_existing_variable(){let s="fn main(){missing=1;}";assert!(execute(s).unwrap_err().contains("undefined variable"));}#[test]fn lexical_shadowing_keeps_outer_value(){let s="fn main(){let x=1; if true {let x=2; print(x);} print(x);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn branch_must_definitely_assign(){let s="fn main(){let x:Int; if true {x=1;} print(x);}";assert!(execute(s).unwrap_err().contains("uninitialized variable"));}#[test]fn both_branches_assign_value(){let s="fn main(){let x:Int; if true {x=1;} else {x=2;} print(x);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn loop_assignment_is_not_definite_after_loop(){let s="fn main(){let x:Int; while false {x=1;} print(x);}";assert!(execute(s).unwrap_err().contains("uninitialized variable"));}}
